// Apify returns the dataset rows as a JSON array.
const payload = $input.all().map((item) => item.json);
if (payload.length === 1 && payload[0] && payload[0].error) {
  throw new Error('Apify error: ' + (payload[0].error.message || JSON.stringify(payload[0].error)));
}
const rows = payload.length === 1 && Array.isArray(payload[0]) ? payload[0] : payload;
const keyField = "placeId";
const seen = new Set();
const clean = [];
for (const row of rows) {
  if (!row || typeof row !== 'object') continue;
  const out = {};
  for (const [k, v] of Object.entries(row)) {
    if (v === null || v === undefined || v === '') continue;
    out[k] = typeof v === 'string' ? v.trim() : v;
  }
  const id = out[keyField] !== undefined ? String(out[keyField]).toLowerCase() : JSON.stringify(out);
  if (seen.has(id)) continue;
  seen.add(id);
  out._source = "https://apify.com/dataspryva/google-maps-business-lead-and-email-finder";
  out._scrapedAt = new Date().toISOString();
  clean.push({ json: out });
}
return clean;
